// Reads every officially.v1 entity created by the demo keys from Tiramisu and writes:
//   public/snapshot.json  — offline fallback the web app shows if the public RPC rate-limits a judge
//   arkiv/evidence.md     — wallet addresses, roles, entity keys and explorer links (generated, do not edit)
import { writeFileSync } from "node:fs"
import { createPublicClient } from "@arkiv-network/sdk"
import { tiramisu } from "@arkiv-network/sdk/chains"
import { str } from "@arkiv-network/sdk/attr"
import { and, eq } from "@arkiv-network/sdk/query"
import { http } from "viem"
import { fromSdkEntity } from "../src/adapters/arkiv/codec"
import { NAMESPACE } from "../src/domain/contract"
import { DEMO } from "../src/infrastructure/demo"
import type { EndpointClaim, Incident, ProjectRecord } from "../src/domain/types"

const EXPLORER = "https://tiramisu.explorer.arkiv.network"
const WALLETS = [
  { role: "Demo Swap root key — signs project records only", address: DEMO.rootKey },
  { role: "Demo Swap publisher key (v2, since the 12 Oct rotation) — endpoint claims, lease renewals, incidents", address: DEMO.publisher },
  { role: "Demo Swap's first publisher key — retired by the root on 12 Oct (its claims read REVOKED; incidents it raised before retirement still count)", address: "0x04a16DA7180594eF2dFFcF70431e809432CE438F" },
  { role: "Simulated attacker — forged claim under Demo Swap's name (for the FORGED demo)", address: "0xcb7074f79E887426Eba3aE9039F0b2ed620a8d6e" },
  { role: "Community wallet — keeps an incident alive (permissionless extension)", address: "0x81989FF0bCd1B25b9b751c53a7266904F83B5ec2" },
]
const c = createPublicClient({ chain: tiramisu, transport: http(undefined, { retryCount: 0 }) })
const all: (ProjectRecord | EndpointClaim | Incident)[] = []
let block = 0n
for (const w of WALLETS.slice(0, 4)) {
  let cursor: string | undefined
  do {
    let q = c.select().where(and(eq("app", str(NAMESPACE)))).createdBy(w.address as `0x${string}`).limit(200)
    if (cursor) q = q.cursor(cursor)
    const r = await q.fetch()
    block = r.blockNumber
    for (const e of r.entities) { const d = fromSdkEntity(e); if (d) all.push(d) }
    cursor = r.cursor
  } while (cursor)
}
const big = (_: string, v: unknown) => (typeof v === "bigint" ? v.toString() : v)
const snap = {
  note: "Snapshot of the synthetic Demo Swap entities, shown only if the public Arkiv RPC rate-limits the viewer. Regenerate with npx tsx scripts/export-evidence.ts.",
  block: block.toString(),
  takenAt: new Date().toISOString(),
  records: all.filter((x) => x.entity === "project"),
  claims: all.filter((x) => x.entity === "endpoint"),
  incidents: all.filter((x) => x.entity === "incident"),
}
writeFileSync("public/snapshot.json", JSON.stringify(snap, big, 2) + "\n")
const blockToDate = (b: bigint) => new Date(Date.now() + Number(b - block) * 2000).toISOString().slice(0, 16).replace("T", " ") + " UTC"
const row = (x: ProjectRecord | EndpointClaim | Incident) => {
  const what = x.entity === "project" ? `publisher ${x.publisher}` : x.entity === "endpoint" ? `${x.target} — ${x.label}` : `${x.title} (severity ${x.severity})`
  return `| \`${x.entity}\` | [${x.key.slice(0, 10)}…](${EXPLORER}/entity/${x.key}) | ${what.replace(/\|/g, "/")} | ${x.creator.slice(0, 8)}… | ${x.owner.slice(0, 8)}… | ~${blockToDate(x.expiresAtBlock)} |`
}
const md = `# On-chain evidence (Tiramisu, chain 7738577)

Generated by \`npx tsx scripts/export-evidence.ts\` at block ${block} (${snap.takenAt}). Do not edit by hand.
All data is synthetic: \`*.example\` domains and made-up contract addresses for a fictional "Demo Swap".

## Wallets that create the entities

| Address | Role |
|---|---|
${WALLETS.map((w) => `| [\`${w.address}\`](${EXPLORER}/address/${w.address}) | ${w.role} |`).join("\n")}

## Live entities (${all.length})

| Type | Entity | What | \`$creator\` | \`$owner\` | Expires (approx.) |
|---|---|---|---|---|---|
${all.map(row).join("\n")}

Endpoints labelled "retires …" were published with a scheduled retirement and lapse on their own during judging (renewals skip them). The burned owner \`0x…dEaD\` on incidents means no key can delete them.
`
writeFileSync("arkiv/evidence.md", md)
console.log(`block ${block}: ${snap.records.length} project, ${snap.claims.length} endpoint, ${snap.incidents.length} incident entities`)
